const history = $steps['fetch-history'].data;
const users = $steps['fetch-users'].data;
const alertsToCreate = [];
const emailsToSend = [];

for (const record of history) {
  if (record.occupancy_pct >= 90.0) {
    const alertId = 'ALT-' + Date.now() + '-' + record.hotel_id;
    const manager = users.find(u => u.hotel_ids.includes(record.hotel_id)) || { email: 'admin@destinovivo.com', name: 'Administrador' };

    alertsToCreate.push({
      alert_id: alertId,
      hotel_id: record.hotel_id,
      alert_type: 'HIGH_DEMAND',
      severity: 'CRITICAL',
      message: `Ocupación crítica (${record.occupancy_pct}%) detectada para la fecha ${record.target_date}`,
      sent_via_gmail: true,
      is_resolved: false,
      created_at: new Date().toISOString()
    });

    emailsToSend.push({
      to: manager.email,
      subject: `[Destino Vivo Alerta CRÍTICA] Alta Ocupación en Hotel ${record.hotel_id}`,
      body: `Hola ${manager.name},\n\nSe ha detectado una ocupación del ${record.occupancy_pct}% para la fecha ${record.target_date}.\nTarifa recomendada calculada: $${record.recommended_rate}.\n\nPor favor revisa el dashboard de Destino Vivo RMS.\n\n--\nDestino Vivo System`
    });
  }
}

return { alertsToCreate, emailsToSend };
